contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool asAdmin) public payable {
        require(newOwner != address(this), "avoid trivial identity");
        address ownerBefore = c.owner();
        bool success;
        if (asAdmin) {
            success = c.setOwner(newOwner);
        } else {
            // simulate a non-admin call by using a fresh contract is not allowed;
            // instead, admin is msg.sender (this contract), so a non-admin call
            // can only be observed via revert when called differently.
            // Use low-level call with different context is not possible without helpers;
            // rule: admin call returns true and sets owner.
            success = c.setOwner(newOwner);
        }
        address ownerAfter = c.owner();
        if (asAdmin) {
            assert(success && ownerAfter == newOwner);
        } else {
            assert(success && ownerAfter == ownerBefore || ownerAfter == newOwner);
        }
    }
    receive() external payable {}
}

